DROP TABLE IF EXISTS `categories`;
CREATE TABLE categories (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    description TEXT,
    icon VARCHAR(64),
    sort_order INT DEFAULT 0
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 12 row(s)
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('agv-amr', 'AGV / AMR Solutions', 'Automated guided vehicles and autonomous mobile robots for tugging, line-side feed and intralogistics.', 'Bot', 12);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('air-line-accessories', 'Air Line Accessories', 'Quick couplings, hoses, reels, FRL units and safety air guns that keep every pneumatic tool at rated power.', 'Wind', 5);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('air-motors', 'Air Motors', 'Compact, stall-proof pneumatic motors for continuous duty in hazardous, wet and high-temperature areas.', 'Fan', 6);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('aluminium-crane-system', 'Aluminum Crane System', 'Modular aluminium rail, jib and gantry systems for low-effort, ergonomic lifting at the workstation.', 'MoveVertical', 9);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('assembly-tightening', 'Assembly & Tightening', 'Electric, cordless and pneumatic nutrunners with controllers, software and full torque-angle traceability.', 'Wrench', 1);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('compressed-air-piping', 'Compressed Air Piping System', 'Corrosion-free aluminium piping for compressed air, vacuum and inert gases — leak-free and reconfigurable.', 'Pipette', 10);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('dispensing-gluing', 'Dispensing & Gluing System', 'Metered dispensing of adhesives, sealants and greases with repeatable bead control and shot monitoring.', 'Droplets', 3);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('hand-tools-storage', 'Hand Tools & Storage System', 'Premium and insulated hand tools, torque wrenches, tool trolleys, workbenches and shadow-board storage.', 'Hammer', 11);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('material-removal', 'Material Removal Tools', 'Grinders, sanders, drills and high-performance abrasives for cutting, deburring, weld prep and finishing.', 'Disc3', 4);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('process-software', 'Process Improvement Software Solutions', 'Torque software, station guidance and production-data platforms that turn tightening results into insight.', 'MonitorCog', 7);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('riveting-systems', 'Riveting System', 'Blind rivet and rivet-nut setting tools — battery, pneumatic and hydro-pneumatic — for structural joining.', 'Hammer', 2);
INSERT INTO `categories` (`id`, `name`, `description`, `icon`, `sort_order`) VALUES ('sockets-fixtures-spm', 'Sockets, Fixtures & SPM Solutions', 'Custom sockets, multi-spindle heads, reaction fixtures and special purpose machines built to your joint.', 'Cog', 8);

-- ---------------------------------------------------------------
-- Table structure & data for `industries`
-- ---------------------------------------------------------------
DROP TABLE IF EXISTS `industries`;
CREATE TABLE industries (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    short VARCHAR(255),
    tagline VARCHAR(255),
    description TEXT,
    image TEXT,
    icon VARCHAR(64),
    accent VARCHAR(16),
    capabilities JSON,
    stat JSON,
    visible TINYINT(1) DEFAULT 1,
    created_at BIGINT DEFAULT 0
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 10 row(s)
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('aerospace', 'Aerospace', 'Aviation-grade joining', 'Where every fastener is mission-critical', 'Aerospace assembly demands certified torque, documented processes and flawless surface integrity. Calibrated tooling, controlled material removal and traceable tightening meet the exacting requirements of airframe, engine and interior fit-out work.', 'https://images.unsplash.com/photo-1712179355181-cd9add37f76a?auto=format&fit=crop&w=1600&q=85', 'Plane', '#4fb6f0', '["Calibrated precision torque tools","Composite & alloy surface finishing","Documented process control","Lightweight ergonomic lifting"]', '{"label":"torque traceability","value":"100%"}', 1, 1784882146067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('automotive', 'Automotive Manufacturing & EV Assembly', 'Precision at line speed', 'Every stage of vehicle build — from body shop to battery pack', 'We support every stage of automotive production: tightening, dispensing, riveting and fastening. From body-in-white and paint shop through final assembly — and into EV battery-module and pack lines — our transducer-controlled tools hold takt time while documenting every safety-critical joint.', 'https://images.unsplash.com/photo-1589320012458-ce28bd1c86b1?auto=format&fit=crop&w=1600&q=85', 'Car', '#7c86f0', '["Smart tightening & torque traceability","EV battery module & pack assembly","Structural blind riveting (BIW)","Dispensing, gluing & sealing systems"]', '{"label":"faster takt cycles","value":"40%"}', 1, 1784882148067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('electronics', 'Electronic', 'Low torque, high volume', 'Energy-efficient precision for low-torque operations', 'Consumer electronics, connected devices and power electronics are assembled at micro-torque with zero tolerance for damaged threads or ESD events. Our screwdrivers, controllers and ESD-safe accessories deliver repeatable results at very low torque, cycle after cycle.', 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1600&q=85', 'CircuitBoard', '#4fb6f0', '["Micro-torque electric screwdrivers","ESD-safe tools & workstations","Screw-counting & error-proofing","Precision dispensing & gluing"]', '{"label":"torque accuracy","value":"±2%"}', 1, 1784882144067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('energy', 'Energy', 'Built to endure', 'World-class bolting for oil & gas, power and wind', 'Power generation, transmission and renewables operate where downtime is measured in lakhs per hour. Hydraulic bolt tensioning, high-torque wrenches and rugged field-service kits deliver controlled load on large-diameter joints — onshore, offshore and up-tower.', 'https://images.unsplash.com/photo-1466611653911-95081537e5b7?auto=format&fit=crop&w=1600&q=85', 'Zap', '#7c86f0', '["Hydraulic bolt tensioning & torquing","High-torque wrenches & reaction arms","Field-service tool kits","Maintenance abrasives & cutting"]', '{"label":"field reliability","value":"99.2%"}', 1, 1784882145067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('heavy-equipment', 'Heavy Equipment and Machinery', 'Big iron, exact torque', 'Reliable, sturdy assembly for total solutions', 'Excavators, loaders, tractors and mining machines are built around large-diameter, high-torque joints. We supply the bolting systems, reaction arms, lifting gear and documented tightening these structures demand — plus the service to keep them running.', 'https://images.unsplash.com/photo-1580901369227-308f6f40bdeb?auto=format&fit=crop&w=1600&q=85', 'Tractor', '#4fd9b4', '["High-torque bolting systems","Torque reaction arms & fixtures","Aluminium crane & lifting systems","Structural riveting"]', '{"label":"assisted lifting","value":"2000 kg"}', 1, 1784882141067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('home-appliances', 'Home Appliances', 'White goods at volume', 'Fast, accurate and durable — shift after shift', 'Washing machines, refrigerators and white goods move fast down the line. Cordless tightening, sheet-metal riveting and inline error-proofing keep cycle times low and rework lower, while ergonomic handling protects operators across long shifts.', 'https://images.unsplash.com/photo-1716193696093-9c54b6a290e5?auto=format&fit=crop&w=1600&q=85', 'WashingMachine', '#4fb6f0', '["Cordless assembly tightening","Sheet-metal blind riveting","Error-proofing & poka-yoke","Line-side material handling"]', '{"label":"units per shift","value":"1200+"}', 1, 1784882143067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('industrial-assembly', 'Industrial Assembly', 'Robust, flexible, repeatable', 'Assembly solutions that flex with your product mix', 'Compressors, pumps and valves, industrial machinery, electric power and outdoor power equipment — high-mix assembly demands tools that change over fast without losing accuracy. We build stations around error-proofing, fixtured tightening and ergonomic handling so quality holds across every variant.', 'https://images.unsplash.com/photo-1717386255773-1e3037c81788?auto=format&fit=crop&w=1600&q=85', 'Factory', '#a78bfa', '["Error-proofing & poka-yoke stations","Fixtured & multi-spindle tightening","Sockets, fixtures & SPM solutions","Workshop tooling & storage systems"]', '{"label":"installations","value":"1200+"}', 1, 1784882147067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('metal-fabrication', 'Metal Fabrication', 'Cut, grind, join, finish', 'High-productivity material removal and air line tools', 'Fabrication shops live on cutting speed and weld-prep quality. Grinders, sanders and high-performance abrasives deliver consistent stock removal, while a properly engineered compressed-air network keeps every tool at full rated power.', 'https://images.unsplash.com/photo-1598302936625-6075fbd98dd7?auto=format&fit=crop&w=1600&q=85', 'Flame', '#a78bfa', '["Material removal tools & abrasives","Grinding, deburring & weld prep","Air line accessories & FRL units","Workshop benches & storage"]', '{"label":"burr-free cutting","value":"1 mm"}', 1, 1784882142067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('railway', 'Railway', 'Built for the long haul', 'Tools and service for high-speed trains, trams and carriages', 'Rolling stock endures decades of vibration and load. We bring documented torque, structural riveting and modular lifting to bogie, body-shell and interior fit-out assembly — plus depot-level service that keeps maintenance windows short.', 'https://images.unsplash.com/photo-1701221602494-699948f33250?auto=format&fit=crop&w=1600&q=85', 'TrainFront', '#7c86f0', '["Documented structural torque","Bogie & body-shell riveting","Modular aluminium crane systems","Depot service & calibration"]', '{"label":"joint documentation","value":"100%"}', 1, 1784882139067);
INSERT INTO `industries` (`id`, `name`, `short`, `tagline`, `description`, `image`, `icon`, `accent`, `capabilities`, `stat`, `visible`, `created_at`) VALUES ('semiconductor', 'Semiconductor Manufacturing', 'Sub-micron discipline', 'Cleanroom-grade tooling for wafer fabrication', 'Fabs are won on contamination control and repeatability. We supply ESD-safe hand tools, particle-conscious fittings and calibrated micro-torque for equipment installation, sub-fab assembly and planned maintenance.', 'https://images.unsplash.com/photo-1576141546153-3e04370b5ff7?auto=format&fit=crop&w=1600&q=85', 'Cpu', '#4fd9b4', '["ESD-safe precision hand tools","Cleanroom-compatible fittings","Calibrated micro-torque control","Equipment install & PM kits"]', '{"label":"torque repeatability","value":"±2%"}', 1, 1784882140067);

-- ---------------------------------------------------------------
-- Table structure & data for `products`
-- ---------------------------------------------------------------
DROP TABLE IF EXISTS `products`;
CREATE TABLE products (
    id VARCHAR(96) PRIMARY KEY,
    slug VARCHAR(160) NOT NULL,
    name VARCHAR(200) NOT NULL,
    brand_id VARCHAR(64),
    brand VARCHAR(128),
    category_id VARCHAR(64),
    line VARCHAR(64),
    industries JSON,
    price BIGINT DEFAULT 0,
    rating DECIMAL(2,1) DEFAULT 0,
    short_desc TEXT,
    description MEDIUMTEXT,
    features JSON,
    specs JSON,
    images JSON,
    featured TINYINT(1) DEFAULT 0,
    special TINYINT(1) DEFAULT 0,
    badge VARCHAR(96),
    visible TINYINT(1) DEFAULT 1,
    KEY idx_products_slug (slug),
    KEY idx_products_category (category_id),
    KEY idx_products_brand (brand_id)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 43 row(s)
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-bolt-tensioner', 'atlas-copco-hydraulic-bolt-tensioner', 'Hydraulic Bolt Tensioner Set', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'bolt-tensioning', '["energy","heavy-equipment","industrial-assembly"]', 1650000, '4.8', 'Sets clamp load directly by stretching the stud — no friction guesswork.', 'Torque fights friction; tensioning does not. A hydraulic tensioner stretches the stud to a known load and the nut is simply run down behind it — the accurate, repeatable method for flanges, wind towers and turbine casings.', '["Direct clamp-load control","Simultaneous multi-stud tensioning","Repeatable, friction-independent","Safer than slugging or hammering"]', '[{"label":"Pressure","value":"Up to 1500 bar"},{"label":"Stud Range","value":"M20 – M100"},{"label":"Pump","value":"Air-driven / electric"},{"label":"Accuracy","value":"± 5% clamp load"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80"]', 0, 0, 'Energy', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-error-proofing', 'atlas-copco-error-proofing-station', 'Error Proofing Station Kit', 'atlas-copco', 'Atlas Copco', 'process-software', 'error-proofing', '["automotive","home-appliances","industrial-assembly"]', 385000, '4.7', 'Socket trays, position detection and guidance that stop the defect.', 'An error-proofing station makes the correct sequence the only possible sequence: the tray knows which socket was taken, the position system knows where the tool is, and the line will not release the part until every joint is confirmed OK.', '["Socket tray selection & confirmation","Tool position detection","Operator guidance display","Part release interlock to PLC"]', '[{"label":"Positions","value":"Up to 16 sockets"},{"label":"Detection","value":"Ultrasonic / RF"},{"label":"Integration","value":"Power Focus & PLC"},{"label":"Feedback","value":"Visual + audible"}]', '["https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-hydraulic-wrench', 'atlas-copco-hydraulic-torque-wrench', 'Hydraulic Torque Wrench', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'wrenches', '["energy","heavy-equipment","railway"]', 980000, '4.7', 'Controlled high torque in confined access — square drive & low clearance.', 'For large-diameter joints where a nutrunner will not fit and a slugging wrench is not acceptable, the hydraulic torque wrench delivers accurate, controlled torque with a reaction arm bearing the load.', '["High torque in tight clearance","Accurate, repeatable output","Square drive & low-clearance heads","Safe reaction arm design"]', '[{"label":"Torque Range","value":"300 – 20,000 Nm"},{"label":"Accuracy","value":"± 3%"},{"label":"Drive","value":"3/4\\" – 2 1/2\\""},{"label":"Pump","value":"Electric / air hydraulic"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-ltv-screwdriver', 'atlas-copco-ltv-pneumatic-screwdriver', 'LTV Pneumatic Screwdriver', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'pneumatic-assembly-tools', '["home-appliances","industrial-assembly","electronics"]', 42000, '4.6', 'Light, fast air screwdriver for high-cycle assembly.', 'Where a joint is not safety-critical but the cycle count is brutal, the LTV air screwdriver wins on cost per rundown — cool-running, light in the hand and almost maintenance-free.', '["Shut-off clutch for repeatable torque","Cool-running at high duty cycles","Very low weight & vibration","Minimal maintenance"]', '[{"label":"Torque Range","value":"0.4 – 12 Nm"},{"label":"Free Speed","value":"500 – 1800 rpm"},{"label":"Air Inlet","value":"1/4\\" BSP"},{"label":"Weight","value":"0.5 kg"}]', '["https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-power-focus', 'atlas-copco-power-focus-6000', 'Power Focus 6000 Controller', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'torque-controllers', '["automotive","industrial-assembly"]', 612000, '4.8', 'Modular tightening controller orchestrating multi-tool stations.', 'Power Focus 6000 is the brain of the smart assembly line — a scalable controller that manages tightening strategies, traceability and line integration across multiple tools from a single intuitive interface.', '["Multi-tool orchestration","Smart tightening strategies","Open protocol & PLC integration","Touch HMI configuration"]', '[{"label":"Channels","value":"Up to 20 tools"},{"label":"Protocols","value":"Open Protocol, PROFINET"},{"label":"Storage","value":"Full result traceability"},{"label":"Display","value":"7\\" touchscreen"}]', '["https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 1, 1, 'Smart Line', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-pro-grinder', 'atlas-copco-pro-angle-grinder', 'PRO Series Angle Grinder', 'atlas-copco', 'Atlas Copco', 'material-removal', 'pro-tools', '["metal-fabrication","heavy-equipment","industrial-assembly"]', 38900, '4.6', 'Industrial air grinder built for full-shift production duty.', 'The PRO range is the everyday industrial workhorse — a governed air grinder that holds speed under load, resists dust ingress and keeps running where consumer-grade tools fail by lunchtime.', '["Speed governor holds rpm under load","Dust-resistant industrial build","Low vibration handle","Safety throttle & wheel guard"]', '[{"label":"Wheel Size","value":"100 – 180 mm"},{"label":"Free Speed","value":"8,500 – 12,000 rpm"},{"label":"Air Consumption","value":"0.9 – 1.4 m³/min"},{"label":"Weight","value":"1.8 kg"}]', '["https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1572981779307-38b8cabb2407?auto=format&fit=crop&w=1000&q=80"]', 0, 0, 'Master Channel Partner', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-qst-spindle', 'atlas-copco-qst-fixtured-spindle', 'QST Fixtured Tightening Spindle', 'atlas-copco', 'Atlas Copco', 'sockets-fixtures-spm', 'fixtured-solutions', '["automotive","industrial-assembly","heavy-equipment"]', 890000, '4.8', 'Compact spindle for multi-point, simultaneous tightening.', 'QST spindles let a fixture close several joints at once, applying even load across a flange or cover in a single cycle. Less distortion, shorter cycle time and a measured result on every spindle.', '["Multi-spindle simultaneous tightening","Compact, close-centre mounting","Individual result per spindle","Built for continuous fixture duty"]', '[{"label":"Torque Range","value":"2 – 500 Nm"},{"label":"Mounting","value":"Fixture / gantry"},{"label":"Control","value":"PF6 FlexSystem"},{"label":"Cooling","value":"Air / passive"}]', '["https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-reaction-arm', 'atlas-copco-torque-reaction-arm', 'Articulated Torque Reaction Arm', 'atlas-copco', 'Atlas Copco', 'sockets-fixtures-spm', 'torque-reaction-arms', '["automotive","heavy-equipment","industrial-assembly"]', 265000, '4.7', 'Takes reaction force off the operator and into the structure.', 'Above about 15 Nm, reaction force is an ergonomic problem and a quality problem. An articulated arm absorbs it, keeps the tool square to the joint and lets the operator work all shift without strain.', '["Absorbs full reaction torque","Free movement in the work envelope","Keeps tool square to the joint","Bench, column or overhead mount"]', '[{"label":"Reaction Torque","value":"Up to 1000 Nm"},{"label":"Reach","value":"600 – 1500 mm"},{"label":"Mounting","value":"Bench / column / rail"},{"label":"Material","value":"Aluminium & steel"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-srb-focus', 'atlas-copco-srb-handheld', 'SRB Handheld Battery Nutrunner', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'cordless-assembly-tools', '["industrial-assembly","automotive","heavy-equipment"]', 215000, '4.7', 'Versatile battery nutrunner for medium-torque assembly.', 'The SRB series brings reliable, repeatable tightening to general assembly with shut-off control, onboard results and effortless battery operation — no hose, no cable, no compromise on the joint.', '["Shut-off torque control","Onboard result storage","Brushless motor","Lightweight balance"]', '[{"label":"Torque Range","value":"10 – 100 Nm"},{"label":"Speed","value":"Up to 700 rpm"},{"label":"Battery","value":"18V Li-Ion"},{"label":"Weight","value":"1.6 kg"}]', '["https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80"]', 0, 0, 'Versatile', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-stwrench', 'atlas-copco-stwrench', 'STwrench Quality Assurance Wrench', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'quality-assurance', '["automotive","aerospace","energy"]', 725000, '4.9', 'Smart audit wrench that measures, judges and records residual torque.', 'The STwrench replaces the click wrench and the clipboard. It measures residual torque and angle on an audit joint, judges it against the spec and stores the result — so the quality audit itself becomes traceable data.', '["Residual torque & angle audit","Interchangeable smart heads","Onboard OK/NOK judgement","Wireless result transfer"]', '[{"label":"Torque Range","value":"1 – 1000 Nm"},{"label":"Accuracy","value":"± 1%"},{"label":"Modes","value":"Audit, production, angle"},{"label":"Connectivity","value":"Wireless"}]', '["https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80"]', 1, 0, 'Audit Ready', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-tensor-es', 'atlas-copco-tensor-es-cordless', 'Tensor ES Electric Nutrunner', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'electric-assembly-tools', '["automotive","aerospace","electronics"]', 489000, '4.9', 'Smart tightening tool with full torque & angle traceability.', 'The Tensor ES delivers transducer-controlled accuracy with real-time torque and angle feedback. Integrated with the Smart Workflow Feature (SWF), every result is documented, traced and error-proofed — the benchmark for critical-joint assembly.', '["Transducer-controlled ±2% torque accuracy","Smart Workflow Feature (SWF) connectivity","Ergonomic, low-reaction grip","OLED display with live results"]', '[{"label":"Torque Range","value":"5 – 50 Nm"},{"label":"Speed","value":"Up to 950 rpm"},{"label":"Accuracy","value":"± 2% Cm/Cmk"},{"label":"Connectivity","value":"Wireless / SWF"},{"label":"Weight","value":"1.1 kg"}]', '["https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80"]', 1, 1, 'SWF Ready', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-tensor-es-screwdriver', 'atlas-copco-tensor-es-screwdriver', 'Tensor ES Electric Screwdriver', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'electric-assembly-tools', '["electronics","home-appliances","semiconductor"]', 312000, '4.8', 'Low-torque electric screwdriver with measured, ESD-safe control.', 'Built for the low end of the torque scale, the Tensor ES screwdriver holds accuracy where a slipping clutch tool would strip the thread. ESD-safe construction and quiet, brushless drive suit electronics and appliance assembly.', '["Accurate at very low torque","ESD-safe housing","Screw-counting & error-proofing ready","Quiet brushless drive"]', '[{"label":"Torque Range","value":"0.3 – 8 Nm"},{"label":"Accuracy","value":"± 2% Cm/Cmk"},{"label":"Weight","value":"0.6 kg"},{"label":"Controller","value":"MicroTorque / PF6"}]', '["https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-tensor-st', 'atlas-copco-tensor-st-nutrunner', 'Tensor ST Electric Nutrunner', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'electric-assembly-tools', '["automotive","industrial-assembly","railway"]', 468000, '4.8', 'The line workhorse — measured tightening for critical joints.', 'Tensor ST covers the broad middle of electric assembly: angle, pistol and straight configurations, all transducer-controlled, all documented. The default choice where a joint has to be right every time and provable afterwards.', '["Angle, pistol & straight variants","Measured torque and angle per rundown","Low reaction, low vibration design","Open protocol result reporting"]', '[{"label":"Torque Range","value":"5 – 200 Nm"},{"label":"Accuracy","value":"± 2% Cm/Cmk"},{"label":"Speed","value":"Up to 1100 rpm"},{"label":"Controller","value":"Power Focus 6000"}]', '["https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80"]', 1, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-tensor-stb', 'atlas-copco-tensor-stb-cordless-angle', 'Tensor STB Cordless Angle Nutrunner', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'cordless-assembly-tools', '["automotive","railway","heavy-equipment"]', 585000, '4.8', 'Cable-free angle nutrunner with full transducer traceability.', 'Tensor STB puts measured, documented tightening wherever the part is — no cable to route, no hose to trip over. The same transducer control as the corded range, with wireless result reporting back to the station controller.', '["Transducer-controlled, fully traceable","Wireless result reporting","Swappable battery, no downtime","Angle head for confined access"]', '[{"label":"Torque Range","value":"10 – 400 Nm"},{"label":"Accuracy","value":"± 2% Cm/Cmk"},{"label":"Battery","value":"18V Li-Ion"},{"label":"Connectivity","value":"Wireless / SWF"}]', '["https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1000&q=80"]', 1, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-tensor-str', 'atlas-copco-tensor-str-nutrunner', 'Tensor STR Electric Nutrunner', 'atlas-copco', 'Atlas Copco', 'assembly-tightening', 'electric-assembly-tools', '["automotive","heavy-equipment","industrial-assembly"]', 545000, '4.9', 'High-torque angle nutrunner for the most demanding line joints.', 'The Tensor STR is built for the heavy end of the electric range — sustained high-torque rundowns with transducer-controlled accuracy and a reaction bar interface that keeps the load off the operator. Every result is measured, judged and reported to the controller.', '["Transducer-controlled torque & angle","Built for continuous high-torque duty","Reaction bar & fixture ready","Full result reporting to Power Focus"]', '[{"label":"Torque Range","value":"20 – 1000 Nm"},{"label":"Accuracy","value":"± 2% Cm/Cmk"},{"label":"Drive","value":"Square 1/2\\" – 1\\""},{"label":"Controller","value":"Power Focus 6000 / 8"}]', '["https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 1, 1, 'High Torque', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('ac-toolsnet', 'atlas-copco-toolsnet-8', 'ToolsNet 8 Process Data Platform', 'atlas-copco', 'Atlas Copco', 'process-software', 'torque-software', '["automotive","industrial-assembly","aerospace"]', 0, '4.8', 'Collects, stores and analyses every tightening result in the plant.', 'ToolsNet 8 turns tightening data into process control. Every rundown from every controller is archived, trended and made searchable — so a warranty question becomes a database query rather than an investigation.', '["Plant-wide result archiving","Trend & capability analysis (Cm/Cmk)","Traceability by VIN, batch or part","Alarms on process drift"]', '[{"label":"Deployment","value":"On-premise / server"},{"label":"Sources","value":"Power Focus & MicroTorque"},{"label":"Retention","value":"Configurable, years"},{"label":"Interfaces","value":"MES / ERP export"}]', '["https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 0, 0, 'Industry 4.0', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('cejn-esafe', 'cejn-esafe-quick-coupling-set', 'eSafe Quick Coupling Set', 'cejn', 'CEJN', 'air-line-accessories', 'esafe-quick-couplings', '["industrial-assembly","metal-fabrication","automotive"]', 12500, '4.8', 'Two-step safety couplings that vent before they release.', 'A charged hose that whips is one of the most common workshop injuries. eSafe couplings vent downstream pressure first and release second — with the highest flow in their size class, so safety costs you nothing in tool performance.', '["Two-step vented safety release","Very high flow, low pressure drop","Full nipple range compatibility","Hardened, long-life construction"]', '[{"label":"Max Working Pressure","value":"10 – 16 bar"},{"label":"Series","value":"300 / 320"},{"label":"Connection","value":"G 1/4\\" – 1/2\\""},{"label":"Material","value":"Steel / composite"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1000&q=80"]', 1, 0, 'OSHA Compliant', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('cejn-multiflow-gun', 'cejn-multiflow-air-fluid-gun', 'Multiflow Air & Fluid Gun', 'cejn', 'CEJN', 'air-line-accessories', 'air-fluid-guns', '["metal-fabrication","industrial-assembly","home-appliances"]', 6800, '4.6', 'OSHA-compliant blow gun with variable flow, rated to 16 bar.', 'The Multiflow gun lets the operator trade flow against noise on the trigger — full force when a part needs clearing, quiet low-flow when it does not. Safety nozzle keeps it OSHA-compliant either way.', '["Variable flow on the trigger","OSHA-compliant safety nozzle","16 bar max working pressure","Air and fluid capable"]', '[{"label":"Max Pressure","value":"16 bar"},{"label":"Inlet","value":"G 1/4\\""},{"label":"Nozzle","value":"Safety, interchangeable"},{"label":"Compliance","value":"OSHA"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('cejn-reel', 'cejn-compressed-air-hose-reel', 'Compressed Air Hose Reel', 'cejn', 'CEJN', 'air-line-accessories', 'hoses-reels', '["metal-fabrication","industrial-assembly","heavy-equipment"]', 34500, '4.7', 'Slow-retraction air reel with guiding mechanism, 5–23 m.', 'Closed and open reels with a slow-retraction mechanism that will not snap the hose back at the operator, plus a guiding arm so the hose lands where you want it. Available in air and 240 V electrical versions.', '["Slow, controlled retraction","Hose guiding mechanism","Easy to install & maintain","Closed (5–17 m) & open (15–23 m)"]', '[{"label":"Hose Length","value":"5 – 23 m"},{"label":"Max Pressure","value":"16 bar"},{"label":"Mounting","value":"Wall / ceiling swivel"},{"label":"Variants","value":"Air & electrical cable"}]', '["https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('eepos-alu-crane', 'eepos-modular-aluminium-crane', 'eepos one Modular Aluminium Crane', 'eepos', 'eepos', 'aluminium-crane-system', 'eepos-one', '["automotive","industrial-assembly","aerospace"]', 1450000, '4.8', 'Lightweight modular crane for ergonomic, flexible material handling.', 'The eepos one aluminium crane combines low dead weight with high rigidity, enabling effortless one-hand movement of loads. Modular profiles configure to any workstation layout and reconfigure when the line changes.', '["Loads up to 2000 kg","Ultra-low rolling resistance","Modular aluminium profiles","Ergonomic single-hand guiding"]', '[{"label":"Capacity","value":"Up to 2000 kg"},{"label":"Span","value":"Up to 8 m"},{"label":"Material","value":"Aircraft-grade aluminium"},{"label":"Mounting","value":"Free-standing / ceiling"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80"]', 1, 1, 'Ergonomic', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('eepos-base', 'eepos-base-crane-media-column', 'eepos base Crane & Media Column', 'eepos', 'eepos', 'aluminium-crane-system', 'eepos-base', '["industrial-assembly","metal-fabrication","automotive"]', 845000, '4.6', 'Standardised entry crane with an integrated air, power & data column.', 'eepos base is the economical way in — a standardised configuration that installs fast, plus a media column that brings compressed air, power and data down to the workstation without a single overhead trailing line.', '["Standardised, fast-install configuration","Media column: air, power & data","Scales into the full eepos system","Keeps services off the floor"]', '[{"label":"Capacity","value":"Up to 500 kg"},{"label":"Column Services","value":"Air, 240 V, data"},{"label":"Material","value":"Anodised aluminium"},{"label":"Install","value":"Bolt-down, no welding"}]', '["https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('eepos-nano', 'eepos-nano-workstation-crane', 'eepos nano Workstation Crane', 'eepos', 'eepos', 'aluminium-crane-system', 'eepos-nano', '["electronics","home-appliances","industrial-assembly"]', 690000, '4.7', 'Compact jib crane sized for a single bench or cell.', 'Not every lift needs a gantry. eepos nano puts the same smooth-running aluminium technology above one workstation, so a repetitive 20 kg lift stops being a back injury waiting to happen.', '["Compact single-station footprint","Very low rolling resistance","Quick bench or column mounting","Expandable into a rail system later"]', '[{"label":"Capacity","value":"Up to 250 kg"},{"label":"Reach","value":"Up to 3 m"},{"label":"Rotation","value":"270° – 360°"},{"label":"Mounting","value":"Column / wall / bench"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gedore-torque', 'gedore-dremaster-torque-wrench', 'DREMASTER Torque Wrench', 'gedore', 'GEDORE', 'hand-tools-storage', 'gedore-torque', '["aerospace","automotive","energy"]', 38500, '4.9', 'Precision click-type torque wrench, calibration certified.', 'The DREMASTER delivers ±3% accuracy with a clear mechanical click. Each wrench ships with an individual calibration certificate, so the torque on the joint is documented from day one.', '["±3% accuracy","Individual calibration certificate","Audible & tactile click","Reversible ratchet head"]', '[{"label":"Range","value":"20 – 200 Nm"},{"label":"Accuracy","value":"± 3%"},{"label":"Drive","value":"1/2\\""},{"label":"Scale","value":"Nm & lbf·ft"}]', '["https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gedore-trolley', 'gedore-workster-tool-trolley', 'WorkSTER Premium Tool Trolley', 'gedore', 'GEDORE', 'hand-tools-storage', 'gedore-storage', '["industrial-assembly","automotive","railway"]', 124000, '4.7', '7-drawer workshop trolley with full tool complement.', 'A mobile workshop in steel — the GEDORE WorkSTER trolley offers smooth ball-bearing drawers, central locking and a curated tool set for professional service teams.', '["7 ball-bearing drawers","Central key locking","Anti-slip worktop","Optional full tool set"]', '[{"label":"Drawers","value":"7"},{"label":"Load / Drawer","value":"30 kg"},{"label":"Material","value":"Powder-coated steel"},{"label":"Castors","value":"4× heavy-duty"}]', '["https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gedore-vde', 'gedore-vde-insulated-tools', 'GEDORE VDE Insulated Hand Tools', 'gedore', 'GEDORE', 'hand-tools-storage', 'gedore-vde', '["energy","electronics","railway"]', 32500, '4.7', 'German-forged 1000 V tools for electrical maintenance.', 'Screwdrivers, pliers and socket sets forged in Germany and insulated to 1000 V — the safe choice for switchgear, control panels and traction maintenance.', '["1000 V rated, individually tested","Drop-forged German tool steel","Ergonomic two-component grips","Available as sets or singles"]', '[{"label":"Rating","value":"1000 V AC"},{"label":"Standard","value":"IEC 60900"},{"label":"Types","value":"Screwdrivers, pliers, sockets"},{"label":"Origin","value":"Made in Germany"}]', '["https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gesipa-accubird', 'gesipa-accubird-pro-rivet-tool', 'AccuBird Pro Blind Rivet Tool', 'gesipa', 'GESIPA', 'riveting-systems', 'pop-rivet-tools', '["automotive","aerospace","industrial-assembly"]', 78500, '4.7', 'Battery-powered blind rivet setting tool with process monitoring.', 'The AccuBird Pro sets blind rivets up to 4.8 mm in all materials with consistent, monitored force. Lightweight and fast, it brings German riveting precision to high-volume structural joining.', '["Sets rivets up to Ø 4.8 mm","Process & setting-force monitoring","Brushless motor, 2.5 kN traction","Quick-change nosepiece system"]', '[{"label":"Rivet Capacity","value":"Ø 2.4 – 4.8 mm"},{"label":"Traction Force","value":"2.5 kN"},{"label":"Stroke","value":"20 mm"},{"label":"Battery","value":"18V Li-Ion"},{"label":"Weight","value":"2.0 kg"}]', '["https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1572981779307-38b8cabb2407?auto=format&fit=crop&w=1000&q=80"]', 1, 1, 'Best Seller', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gesipa-firebird', 'gesipa-firebird-pro-rivet-nut', 'FireBird Pro Rivet-Nut Setter', 'gesipa', 'GESIPA', 'riveting-systems', 'nut-insert-tools', '["automotive","industrial-assembly","home-appliances"]', 89900, '4.6', 'High-speed blind rivet-nut tool for threaded fastening.', 'FireBird Pro sets blind rivet nuts up to M10 with programmable stroke and force control — the fast way to add a strong, load-bearing thread to thin-walled structures with no back access.', '["Sets rivet nuts up to M10","Stroke & force programmable","Fast cycle, low fatigue","Digital setting feedback"]', '[{"label":"Capacity","value":"M3 – M10"},{"label":"Setting Force","value":"20 kN"},{"label":"Battery","value":"18V Li-Ion"},{"label":"Weight","value":"2.2 kg"}]', '["https://images.unsplash.com/photo-1572981779307-38b8cabb2407?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gesipa-firefox', 'gesipa-firefox-nut-insert-tool', 'FireFox Hydro-Pneumatic Nut Insert Tool', 'gesipa', 'GESIPA', 'riveting-systems', 'nut-insert-tools', '["automotive","industrial-assembly","metal-fabrication"]', 112000, '4.7', 'Air-hydraulic nut setter for continuous line production.', 'FireFox is the station tool for rivet-nut work: hydro-pneumatic power, a stable setting stroke and the endurance to run all shift without the recharge cycle of a battery tool.', '["Sets nuts up to M12","Constant setting stroke","Continuous production duty","Fast thread engagement & release"]', '[{"label":"Capacity","value":"M4 – M12"},{"label":"Setting Force","value":"Up to 26 kN"},{"label":"Air Pressure","value":"5 – 7 bar"},{"label":"Weight","value":"2.4 kg"}]', '["https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gesipa-gav', 'gesipa-gav-automatic-feed', 'GAV Automatic Feed Riveting System', 'gesipa', 'GESIPA', 'riveting-systems', 'gav-automatic-tools', '["automotive","home-appliances","industrial-assembly"]', 1980000, '4.8', 'Feeds rivets to the tool nose — the operator never handles a fastener.', 'The GAV automatic system delivers each rivet to the nosepiece ready to set. Cycle time drops, the wrong-rivet error disappears, and the operator\'s hands stay on the part instead of in a parts bin.', '["Automatic rivet feed to nosepiece","Eliminates wrong-rivet errors","Significant cycle-time reduction","Robot & fixture integration ready"]', '[{"label":"Rivet Capacity","value":"Ø 2.4 – 5.0 mm"},{"label":"Feed Rate","value":"Up to 30 rivets/min"},{"label":"Supply","value":"Bowl feeder"},{"label":"Integration","value":"Manual, fixture or robot"}]', '["https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1572981779307-38b8cabb2407?auto=format&fit=crop&w=1000&q=80"]', 0, 0, 'Automation', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gesipa-manual', 'gesipa-manual-riveting-tools', 'Manual Riveting Tool Range', 'gesipa', 'GESIPA', 'riveting-systems', 'manual-tools', '["metal-fabrication","industrial-assembly","railway"]', 18500, '4.5', 'Hand and lever riveting tools for field work and low volumes.', 'Every powered station needs a manual backup. GESIPA hand and lever tools set blind rivets and nuts anywhere there is no air, no power and no room for a bigger tool.', '["No power or air required","Hardened jaws, long service life","Full nosepiece range included","Compact for field service kits"]', '[{"label":"Rivet Capacity","value":"Ø 2.4 – 5.0 mm"},{"label":"Type","value":"Hand / lever"},{"label":"Nosepieces","value":"4 supplied"},{"label":"Weight","value":"0.6 – 1.4 kg"}]', '["https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('gesipa-taurus', 'gesipa-taurus-rivet-tool', 'Taurus Hydro-Pneumatic Rivet Tool', 'gesipa', 'GESIPA', 'riveting-systems', 'pop-rivet-tools', '["automotive","railway","heavy-equipment"]', 96500, '4.8', 'Air-hydraulic riveter for structural rivets up to 6.4 mm.', 'Where AccuBird ends, Taurus begins. The hydro-pneumatic Taurus range sets large structural and stainless rivets shift after shift, with an integral mandrel container that keeps the workstation clean.', '["Sets rivets up to Ø 6.4 mm","High traction force, short cycle","Integral mandrel collection","Continuous line-duty design"]', '[{"label":"Rivet Capacity","value":"Ø 2.4 – 6.4 mm"},{"label":"Traction Force","value":"Up to 18 kN"},{"label":"Air Pressure","value":"5 – 7 bar"},{"label":"Weight","value":"2.3 kg"}]', '["https://images.unsplash.com/photo-1572981779307-38b8cabb2407?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80"]', 1, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('hoffmann-digital-torque', 'hoffmann-holex-digital-torque-wrench', 'HOLEX Digital Torque Wrench', 'hoffmann-group', 'Hoffmann Group', 'hand-tools-storage', 'torque-technology', '["automotive","aerospace","energy"]', 62000, '4.8', 'Digital wrench with target display, memory and audit export.', 'A digital torque wrench removes the argument about whether the click was heard. Live torque on screen, target and tolerance stored, results logged and exportable for the audit file.', '["Live torque & angle display","Stored targets with tolerance bands","Result memory with export","Audible, visual & haptic alert"]', '[{"label":"Range","value":"1 – 340 Nm (by model)"},{"label":"Accuracy","value":"± 2%"},{"label":"Drive","value":"1/4\\" – 1/2\\""},{"label":"Memory","value":"Up to 1000 results"}]', '["https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('hoffmann-trolley', 'hoffmann-garant-tool-trolley', 'GARANT Tool Trolley', 'hoffmann-group', 'Hoffmann Group', 'hand-tools-storage', 'trolleys-benches-storage', '["industrial-assembly","automotive","metal-fabrication"]', 168000, '4.8', 'Mobile workshop with full-extension drawers and foam inlays.', 'A GARANT trolley gives every tool a defined home. Full-extension drawers, central locking and cut foam inlays mean a missing tool is visible at a glance — the practical foundation of a 5S floor.', '["Full-extension ball-bearing drawers","Central locking","Foam inlay tool control","Anti-slip worktop"]', '[{"label":"Drawers","value":"7 – 8"},{"label":"Load / Drawer","value":"40 kg"},{"label":"Material","value":"Powder-coated steel"},{"label":"Castors","value":"4× heavy-duty"}]', '["https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80"]', 1, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('hoffmann-vde', 'hoffmann-garant-vde-tool-set', 'GARANT VDE Insulated Tool Set', 'hoffmann-group', 'Hoffmann Group', 'hand-tools-storage', 'industrial-hand-tools', '["electronics","energy","automotive"]', 48500, '4.7', '1000 V individually tested tools for live-side working.', 'Panel shops, EV lines and switchyards need tools that are certified, not merely coated. Every piece in this set is individually tested to 10,000 V and rated for work at 1000 V AC.', '["Individually tested to 10,000 V","Rated for 1000 V AC working","Two-component insulation","Supplied in a roll or case"]', '[{"label":"Rating","value":"1000 V AC"},{"label":"Standard","value":"IEC 60900"},{"label":"Pieces","value":"12 – 25 (by set)"},{"label":"Case","value":"Tool roll / hard case"}]', '["https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('jg-pneumatic', 'john-guest-pneumatic-fitting', 'Pneumatic Push-In Fitting Range', 'john-guest', 'John Guest', 'air-line-accessories', 'jg-pneumatics', '["industrial-assembly","automotive"]', 6500, '4.6', 'Compact push-in fittings for compressed-air automation.', 'A complete range of compact pneumatic fittings engineered for fast assembly and reliable, vibration-resistant air connections on automated equipment.', '["Compact footprint","Vibration resistant","360° swivel elbows","Nickel-plated brass thread"]', '[{"label":"Tube OD","value":"4 – 16 mm"},{"label":"Pressure","value":"Up to 16 bar"},{"label":"Thread","value":"BSPT / NPT"},{"label":"Body","value":"Acetal / brass"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('jg-speedfit', 'john-guest-speedfit-connector', 'Speedfit Push-Fit Plumbing Range', 'john-guest', 'John Guest', 'air-line-accessories', 'speedfit-plumbing', '["industrial-assembly","home-appliances"]', 8900, '4.8', 'Tool-free push-fit fittings for hot & cold water services.', 'John Guest Speedfit creates an instant, secure, leak-free joint with a simple push — no flame, flux or solvent. The range covers barrier pipe, connectors, elbows, tees, tap connectors, stop ends, inserts and clips.', '["Tool-free push-to-connect","Leak-free O-ring seal","Demountable & reusable","WRAS / NSF approved"]', '[{"label":"Tube OD","value":"4 – 22 mm"},{"label":"Pressure","value":"Up to 20 bar"},{"label":"Temp","value":"-20 to 65 °C"},{"label":"Material","value":"Acetal copolymer"}]', '["https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1000&q=80"]', 0, 0, 'Push-Fit', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('legris-push-in', 'legris-push-in-fitting-range', 'Legris Push-In Fitting Range', 'legris', 'Legris', 'air-line-accessories', 'push-in-fittings', '["industrial-assembly","automotive","semiconductor"]', 7200, '4.7', 'Tool-free brass & technopolymer fittings that stay leak-tight.', 'Push the tube in and the joint is made — no tools, no PTFE tape, no rework. The Legris range covers straights, elbows, tees, bulkheads and manifolds in both brass and technopolymer.', '["Instant tool-free connection","Holds through vibration & cycling","Brass and technopolymer bodies","Full geometry range"]', '[{"label":"Tube OD","value":"4 – 16 mm"},{"label":"Pressure","value":"Up to 20 bar"},{"label":"Temp","value":"-20 to 80 °C"},{"label":"Thread","value":"BSPP / BSPT / NPT"}]', '["https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('legris-tubing', 'legris-calibrated-tubing', 'Calibrated Pneumatic Tubing', 'legris', 'Legris', 'air-line-accessories', 'tubing-hose', '["industrial-assembly","electronics","automotive"]', 4900, '4.6', 'PA, PU and PE tube calibrated to the fitting range.', 'A push-in seal is only as good as the tube it grips. Legris tubing is calibrated to the fitting tolerance and colour-coded for circuit identification, so the joint is engineered rather than improvised.', '["Calibrated OD for reliable sealing","PA, PU and PE materials","Full colour range for circuit ID","Available in multi-tube bundles"]', '[{"label":"Tube OD","value":"4 – 16 mm"},{"label":"Materials","value":"PA / PU / PE"},{"label":"Pressure","value":"Up to 20 bar"},{"label":"Coil Length","value":"25 / 100 m"}]', '["https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('pferd-burr-set', 'pferd-carbide-burr-set', 'Carbide Burr & Deburring Set', 'pferd', 'PFERD', 'material-removal', 'burrs-files-brushes', '["metal-fabrication","aerospace","heavy-equipment"]', 14800, '4.7', 'Carbide burrs and files for the edges a disc cannot reach.', 'Weld prep, internal edges, cast flash and radius work — carbide burrs and files cut cleanly where a grinding disc simply will not fit, with tooth geometries matched to the material.', '["Cut geometries per material","Long-life tungsten carbide","Reaches internal & profiled edges","Supplied as a graded set"]', '[{"label":"Shank","value":"6 mm"},{"label":"Shapes","value":"Cylindrical, ball, tree, cone"},{"label":"Materials","value":"Steel, stainless, alloy, cast"},{"label":"Set Size","value":"5 – 10 pieces"}]', '["https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('pferd-cut-disc', 'pferd-sg-steelox-cutting-disc', 'SG STEELOX Cutting Disc', 'pferd', 'PFERD', 'material-removal', 'cutting-discs', '["metal-fabrication","automotive","energy"]', 4200, '4.6', 'Ultra-thin high-performance cutting disc for steel & stainless.', 'PFERD SG STEELOX discs cut steel and stainless with minimal burr and maximum life. The 1 mm profile delivers fast, cool, precise cuts with low material loss — and less work in the deburring step that follows.', '["1 mm ultra-thin profile","Steel & stainless (INOX)","Cool, burr-free cutting","Long service life"]', '[{"label":"Diameter","value":"125 mm"},{"label":"Thickness","value":"1.0 mm"},{"label":"Max RPM","value":"12,200 rpm"},{"label":"Material","value":"Aluminium oxide"}]', '["https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1572981779307-38b8cabb2407?auto=format&fit=crop&w=1000&q=80"]', 0, 0, 'Pack of 25', 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('pferd-flap-disc', 'pferd-polifan-flap-disc', 'POLIFAN Flap Disc', 'pferd', 'PFERD', 'material-removal', 'grinding-finishing', '["metal-fabrication","aerospace","heavy-equipment"]', 5600, '4.7', 'Zirconia flap disc for aggressive grinding and finishing.', 'POLIFAN combines high stock removal with a fine finish, letting you grind and finish in a single step on steel, stainless and alloys — one disc instead of two operations.', '["Zirconia alumina grain","Grind & finish in one step","Cool operation","Consistent performance to the last flap"]', '[{"label":"Diameter","value":"115 mm"},{"label":"Grit","value":"Z40 / Z60 / Z80"},{"label":"Max RPM","value":"13,300 rpm"},{"label":"Backing","value":"Fibreglass"}]', '["https://images.unsplash.com/photo-1572981779307-38b8cabb2407?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('prod-test', 'test', 'test', 'atlas-copco', 'Atlas Copco', 'dispensing-gluing', 'electric-assembly-tools', '["railway"]', 0, '4.5', '', '', '["lorem-feature"]', '[{"label":"weight","value":"15 gm"}]', '["https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&w=1000&q=80"]', 0, 0, NULL, 1);
INSERT INTO `products` (`id`, `slug`, `name`, `brand_id`, `brand`, `category_id`, `line`, `industries`, `price`, `rating`, `short_desc`, `description`, `features`, `specs`, `images`, `featured`, `special`, `badge`, `visible`) VALUES ('transair-piping', 'transair-aluminium-air-piping', 'Transair Aluminium Compressed Air Piping', 'transair', 'Transair', 'compressed-air-piping', 'compressed-air-piping', '["industrial-assembly","automotive","metal-fabrication"]', 0, '4.9', 'Clean-bore aluminium piping — leak-free, low pressure drop, reconfigurable.', 'Steel pipe corrodes, drops pressure and takes a week to re-route. Transair\'s calibrated aluminium system stays clean-bore for life, pushes together without welding or threading, and can be reconfigured over a weekend when the line moves.', '["Corrosion-free, clean bore for life","Push-together — no welding or threading","Removable and reconfigurable joints","Approved for air, vacuum & inert gases"]', '[{"label":"Pipe Sizes","value":"Ø 16.5 – 168 mm"},{"label":"Max Pressure","value":"16 bar"},{"label":"Temp","value":"-20 to 60 °C"},{"label":"Material","value":"Calibrated aluminium"}]', '["https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&w=1000&q=80"]', 1, 1, 'Energy Saving', 1);

-- ---------------------------------------------------------------
-- Table structure & data for `inquiries`
-- ---------------------------------------------------------------
DROP TABLE IF EXISTS `inquiries`;
CREATE TABLE inquiries (
    id VARCHAR(96) PRIMARY KEY,
    name VARCHAR(160) NOT NULL,
    email VARCHAR(200) NOT NULL,
    phone VARCHAR(64),
    address VARCHAR(255),
    message TEXT,
    product_id VARCHAR(96),
    product_name VARCHAR(200),
    status ENUM('new','read','responded','closed') NOT NULL DEFAULT 'new',
    created_at BIGINT NOT NULL,
    KEY idx_inquiries_status (status),
    KEY idx_inquiries_created (created_at)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3 row(s)
INSERT INTO `inquiries` (`id`, `name`, `email`, `phone`, `address`, `message`, `product_id`, `product_name`, `status`, `created_at`) VALUES ('seed-1', 'Rohan Mehta', 'rohan@tatamotors.example', '+91 98250 11223', 'Sanand, Gujarat', 'Interested in Tensor ES nutrunners for our BIW line. Please share a quote for 12 units with SWF integration.', 'ac-tensor-es', 'Tensor ES Electric Nutrunner', 'new', 1784864148358);
